import React from 'react';
import { 
  ChevronLeft, 
  ChevronRight, 
  Calendar as CalendarIcon,
  CheckCircle2,
  XCircle,
  Clock,
  Search
} from 'lucide-react';
import { DayData } from '../types';

interface HistoryViewProps {
  calendarData: DayData[];
  currentDay: number;
  onSelectDay: (day: number) => void;
}

const HistoryView: React.FC<HistoryViewProps> = ({ 
  calendarData, 
  currentDay,
  onSelectDay 
}) => {
  const [selectedMonth, setSelectedMonth] = React.useState(new Date(2026, 3, 1)); // April 1st

  const getStatusColor = (day: DayData) => {
    if (!day.completed && day.day < currentDay) return 'bg-red-500/10 text-red-400 border-red-500/20';
    if (day.completed) {
      if (day.grade === 'A+' || day.grade === 'A') return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.1)]';
      if (day.grade === 'B') return 'bg-blue-500/10 text-blue-400 border-blue-500/20';
      return 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20';
    }
    if (day.day === currentDay) return 'bg-blue-600 text-white border-blue-400 shadow-[0_0_20px_rgba(59,130,246,0.3)] scale-105 z-10';
    return 'bg-white/5 text-slate-500 border-white/5';
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-fade-in">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="space-y-1">
          <h2 className="text-sm font-bold tracking-widest text-purple-400 uppercase">Consistency Map</h2>
          <h1 className="text-4xl font-bold tracking-tight">180-Day Grid</h1>
          <p className="text-slate-400 font-medium">Track your progress across the entire journey.</p>
        </div>

        <div className="flex items-center gap-4">
           <div className="relative group">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-blue-400 transition-colors" size={16} />
              <input 
                type="text" 
                placeholder="Search day..." 
                className="pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded-xl text-sm outline-none focus:border-blue-500/50 transition-all w-48"
              />
           </div>
        </div>
      </div>

      {/* Stats Summary Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Days', value: '180', color: 'text-slate-300' },
          { label: 'Completed', value: calendarData.filter(d => d.completed).length, color: 'text-emerald-400' },
          { label: 'Current Phase', value: currentDay <= 30 ? '1' : currentDay <= 60 ? '2' : '3', color: 'text-blue-400' },
          { label: 'Remaining', value: 180 - currentDay + 1, color: 'text-purple-400' }
        ].map((stat, i) => (
          <div key={i} className="glass-card p-4 border-white/5 text-center">
            <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold mb-1">{stat.label}</p>
            <p className={`text-2xl font-black ${stat.color}`}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* 180-Day Grid */}
      <div className="glass-card p-8 border-white/10 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-5">
          <CalendarIcon size={120} className="text-white" />
        </div>

        <div className="grid grid-cols-5 sm:grid-cols-10 lg:grid-cols-15 xl:grid-cols-20 gap-3 relative z-10">
          {calendarData.map((day) => (
            <button
              key={day.day}
              onClick={() => onSelectDay(day.day)}
              className={`aspect-square rounded-lg border flex flex-col items-center justify-center transition-all duration-300 hover:scale-110 active:scale-95 group relative ${getStatusColor(day)}`}
            >
              <span className="text-[10px] font-bold opacity-60">D</span>
              <span className="text-sm font-black">{day.day}</span>

              {/* Tooltip on hover */}
              <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-2 bg-slate-900 text-white text-[10px] rounded-lg opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap shadow-2xl border border-white/10 z-50">
                 <p className="font-bold mb-1">Day {day.day}</p>
                 <p className="text-slate-400">{new Date(day.date).toLocaleDateString()}</p>
                 {day.completed && <p className="text-blue-400 mt-1 font-black">Grade: {day.grade}</p>}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-6 px-4">
        {[
          { label: 'Current Day', color: 'bg-blue-600 shadow-[0_0_10px_rgba(59,130,246,0.5)]' },
          { label: 'Excellent (A/A+)', color: 'bg-emerald-500/20 border-emerald-500/40' },
          { label: 'Completed (B/C/D)', color: 'bg-blue-500/20 border-blue-500/40' },
          { label: 'Missed/Failed', color: 'bg-red-500/20 border-red-500/40' },
          { label: 'Upcoming', color: 'bg-white/5 border-white/10' }
        ].map((item, i) => (
          <div key={i} className="flex items-center gap-2">
            <div className={`w-3 h-3 rounded-sm border ${item.color}`} />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{item.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default HistoryView;
